  for await(const chunk of chunks) {
    if(typeof chunk==='string') {consume(decoder.end());consume(chunk);}
    else if(Buffer.isBuffer(chunk)) consume(decoder.write(chunk));
    else throw Error('invalid NDJSON chunk');
  }
  consume(decoder.end());if(pending.trim()) records.push(JSON.parse(pending));
  return catalog.applyBatch(records.map(record=>({type:'add',record})));
