"}

{"path":"src/csv.mjs","content":"export function parseCSV(text) {
  if (typeof text !== 'string') throw Error('CSV must be text');
  if (!text.length) return [];
  const rows=[]; let row=[],field='',state='start',ended=false;
  for(let i=0;i<text.length;i++) {
    const c=text[i]; ended=false;
    if(state==='quoted') {
      if(c==='"') { if(text[i+1]==='"') {field+='"';i++;} else state='closed'; }
      else field+=c;
    } else if(c===',') {row.push(field);field='';state='start';}
    else if(c==='\r' || c==='\n') {
      if(c==='\r' && text[i+1]==='\n') i++;
      row.push(field);rows.push(row);row=[];field='';state='start';ended=true;
    } else if(c==='"' && state==='start') state='quoted';
    else {
      if(c==='"' || state==='closed') throw Error('invalid CSV quote');
      field+=c;state='plain';
    }
  }
  if(state==='quoted') throw Error('unclosed CSV quote');
  if(!ended) {row.push(field);rows.push(row);}
  return rows;
}
export function stringifyCSV(rows) {
  return rows.map(row=>row.map(value=>{
    const s=String(value);
    return /[",\r\n]/.test(s) ? '"'+s.replaceAll('"','""')+'"' : s;
  }).join(',')).join('\r\n');
}
"}

{"path":"src/catalog.mjs","content":"import {parseVersion} from './version.mjs';
const object = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const copy = v => structuredClone(v);
export function normalizeRecord(record) {
  if(!object(record)) throw Error('invalid record');
  const {id,name,version,tags,dependencies}=record;
  if(typeof id!=='string' || !id.trim() || typeof name!=='string' || !name.trim()) throw Error('invalid id/name');
  parseVersion(version);
  if(!Array.isArray(tags) || tags.some(t=>typeof t!=='string')) throw Error('invalid tags');
  if(!Array.isArray(dependencies) || dependencies.some(d=>typeof d!=='string' || !d.trim())) throw Error('invalid dependencies');
  return {id:id.trim(),name:name.trim(),version,tags:[...new Set(tags.map(t=>t.trim().toLowerCase()).filter(Boolean))].sort(),dependencies:[...new Set(dependencies)]};
}
export function createCatalog(seed=[]) {
  if(!Array.isArray(seed)) throw Error('invalid seed');
  let entries=new Map();
  function apply(map,op) {
    if(!object(op)) throw Error('invalid operation');
    if(op.type==='add') {
      const record=normalizeRecord(op.record);
      if(map.has(record.id)) throw Error('duplicate id: '+record.id);
      map.set(record.id,record);return copy(record);
    }
    if(op.type==='update') {
      if(!map.has(op.id)) throw Error('unknown id: '+op.id);
      if(!object(op.patch) || ('id' in op.patch && op.patch.id!==op.id)) throw Error('invalid patch/id change');
      const record=normalizeRecord({...map.get(op.id),...op.patch});
      map.set(op.id,record);return copy(record);
    }
    if(op.type==='remove') {
      if(typeof op.id!=='string' || !op.id.trim()) throw Error('invalid id');
      return map.delete(op.id);
    }
    throw Error('invalid operation');
  }
  const api={
    list:()=>copy([...entries.values()].sort((a,b)=>a.id<b.id?-1:a.id>b.id?1:0)),
    get:id=>entries.has(id)?copy(entries.get(id)):null,
    add:record=>apply(entries,{type:'add',record}),
    update:(id,patch)=>apply(entries,{type:'update',id,patch}),
    remove:id=>apply(entries,{type:'remove',id}),
    applyBatch:operations=>{
      if(!Array.isArray(operations)) throw Error('invalid operations');
      const next=new Map(entries);
      const results=operations.map(op=>apply(next,op));
      entries=next;return results;
    }
  };
  api.applyBatch(seed.map(record=>({type:'add',record})));
  return api;
}
"}

{"path":"src/search.mjs","content":"import {parseVersion,compareVersions} from './version.mjs';
export function searchRecords(records,query={}) {
  if(!query || typeof query!=='object' || Array.isArray(query)) throw Error('invalid query');
  const {sortBy='id',order='asc',offset=0,limit=20,text='',tags=[]}=query;
  if(!['id','name','version'].includes(sortBy) || !['asc','desc'].includes(order)) throw Error('invalid sort/order');
  if(!Number.isInteger(offset) || offset<0 || !Number.isInteger(limit) || limit<1 || limit>100) throw Error('invalid paging');
  if(typeof text!=='string' || !Array.isArray(tags) || tags.some(t=>typeof t!=='string')) throw Error('invalid text/tags');
  if(query.versionMin!==undefined) parseVersion(query.versionMin);
  if(query.versionMax!==undefined) parseVersion(query.versionMax);
  const term=text.trim().toLowerCase(), required=[...new Set(tags.map(t=>t.trim().toLowerCase()).filter(Boolean))];
  const cmp=(a,b)=>a<b?-1:a>b?1:0;
  const items=records.filter(r=>(r.name.toLowerCase().includes(term)||r.id.toLowerCase().includes(term)) && required.every(t=>r.tags.map(t=>t.trim().toLowerCase()).includes(t)) && (query.versionMin===undefined||compareVersions(r.version,query.versionMin)>=0) && (query.versionMax===undefined||compareVersions(r.version,query.versionMax)<=0));
  items.sort((a,b)=>((sortBy==='version'?compareVersions(a.version,b.version):cmp(a[sortBy],b[sortBy]))*(order==='asc'?1:-1))||cmp(a.id,b.id));
  return {items:structuredClone(items.slice(offset,offset+limit)),total:items.length,offset,limit};
}
"}

{"path":"src/graph.mjs","content":"export function planDependencies(records,requestedIds) {
  if(!Array.isArray(requestedIds) || requestedIds.some(id=>typeof id!=='string')) throw Error('invalid requested ids');
  const nodes=new Map(records.map(r=>[r.id,r])),done=new Set(),active=new Set(),path=[],result=[];
  function visit(id) {
    if(!nodes.has(id)) throw Error('missing id: '+id);
    if(active.has(id)) throw Error('cycle: '+[...path.slice(path.indexOf(id)),id].join(' -> '));
    if(done.has(id)) return;
    active.add(id);path.push(id);
    for(const dependency of nodes.get(id).dependencies) visit(dependency);
    path.pop();active.delete(id);done.add(id);result.push(id);
  }
  requestedIds.forEach(visit);return result;
}
export function reverseDependencies(records,id) {
  if(!records.some(r=>r.id===id)) throw Error('unknown id: '+id);
  const reverse=new Map();
  for(const r of records) for(const d of r.dependencies) {
    if(!reverse.has(d)) reverse.set(d,[]);
    reverse.get(d).push(r.id);
  }
  const seen=new Set([id]),queue=[id];
  for(let i=0;i<queue.length;i++) for(const next of reverse.get(queue[i])??[]) if(!seen.has(next)) {seen.add(next);queue.push(next);}
  seen.delete(id);return [...seen].sort();
}
"}

{"path":"src/transfer.mjs","content":"import {StringDecoder} from 'node:string_decoder';
import {parseCSV,stringifyCSV} from './csv.mjs';
const header=['id','name','version','tags','dependencies'];
export function exportCSV(records) {
  return stringifyCSV([header,...records.map(r=>[r.id,r.name,r.version,r.tags.join('|'),r.dependencies.join('|')])]);
